import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div className="component-preview relative isolate flex w-full min-w-0 items-center justify-center font-sans text-foreground contain-layout">
      {children}
    </div>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";
export default function Demo() {
  return (
    <>
      <Button
        onClick={() =>
          toast.add({
            id: "toast-demo-saved",
            title: "Saved",
            description: "Your changes have been saved.",
          })
        }
      >
        Show toast
      </Button>
    </>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

export function ToastPromise() {
  function showToast() {
    void toast.promise(
      new Promise<{ name: string }>((resolve) => {
        window.setTimeout(() => resolve({ name: "Event" }), 2000);
      }),
      {
        loading: "Creating event…",
        success: (data) => `${data.name} created.`,
        error: "Could not create event.",
      },
    );
  }

  return (
    <Button variant="outline" onClick={showToast}>
      Create Event
    </Button>
  );
}

import { Button } from "@/registry/erbium/ui/button";
import { toast } from "@/registry/erbium/ui/toast";

export function ToastTypes() {
  return (
    <div className="flex flex-wrap gap-2">
      <Button
        variant="outline"
        onClick={() =>
          toast.add({ id: "toast-type-default", description: "Event has been created." })
        }
      >
        Default
      </Button>
      <Button
        variant="outline"
        onClick={() =>
          toast.add({
            id: "toast-type-success",
            type: "success",
            description: "Event has been created.",
          })
        }
      >
        Success
      </Button>
      <Button
        variant="outline"
        onClick={() =>
          toast.add({
            id: "toast-type-info",
            type: "info",
            description: "Arrive 10 minutes before the event.",
          })
        }
      >
        Info
      </Button>
      <Button
        variant="outline"
        onClick={() =>
          toast.add({
            id: "toast-type-warning",
            type: "warning",
            description: "The event cannot start before 8:00 AM.",
          })
        }
      >
        Warning
      </Button>
      <Button
        variant="outline"
        onClick={() =>
          toast.add({
            id: "toast-type-error",
            type: "error",
            description: "The event could not be created.",
            priority: "high",
          })
        }
      >
        Error
      </Button>
    </div>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import { DocsContainer, type DocsContainerProps } from "@storybook/addon-docs/blocks";
import type { PropsWithChildren } from "react";
function ToastDocsContainer(props: PropsWithChildren<DocsContainerProps>) { return <DocsContainer {...props}><ShowcaseProviders toast>{props.children}</ShowcaseProviders></DocsContainer>; }
import { Toast } from "@/registry/erbium/ui/toast";

import type { Meta, StoryObj } from "@storybook/react";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Button } from \"@/registry/erbium/ui/button\";\nimport { toast } from \"@/registry/erbium/ui/toast\";\n\nconst Example = (args: { type: \"success\" | \"info\" | \"warning\" | \"error\"; description: string }) => (\n  <Button\n    onClick={() =>\n      toast.add({\n        id: `toast-playground-${args.type}`,\n        type: args.type,\n        description: args.description,\n      })\n    }\n  >\n    Show toast\n  </Button>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/toast-demo\";\n\nconst Example = () => (\n  <div className=\"w-full min-w-72 max-w-2xl p-4\">\n    <Demo />\n  </div>\n);\n\nexport default Example;\n";

import TypesExample from "./variants/types";

const TypesSource = "import { ToastTypes } from \"../examples/upstream/toast-types\";\n\nconst Example = () => <ToastTypes />;\n\nexport default Example;\n";

import PromiseExample from "./variants/promise";

const PromiseSource = "import { ToastPromise } from \"../examples/upstream/toast-promise\";\n\nconst Example = () => <ToastPromise />;\n\nexport default Example;\n";

import ActionExample from "./variants/action";

const ActionSource = "import { Button } from \"@/registry/erbium/ui/button\";\nimport { toast } from \"@/registry/erbium/ui/toast\";\n\nconst Example = () => (\n  <Button\n    onClick={() =>\n      toast.add({\n        title: \"Draft saved\",\n        actionProps: {\n          children: \"Undo\",\n          onClick: () => toast.add({ title: \"Draft restored\" }),\n        },\n      })\n    }\n  >\n    Show action toast\n  </Button>\n);\n\nexport default Example;\n";

import ProgressExample from "./variants/progress";

const ProgressSource = "import { Button } from \"@/registry/erbium/ui/button\";\nimport { toast } from \"@/registry/erbium/ui/toast\";\n\nconst Example = () => (\n  <Button\n    variant=\"outline\"\n    onClick={() => {\n      const id = toast.add({ title: \"Syncing changes…\", type: \"loading\", timeout: 0 });\n      window.setTimeout(() => {\n        toast.update(id, { title: \"Changes synced\", type: \"success\", timeout: 4000 });\n      }, 1200);\n    }}\n  >\n    Show progress toast\n  </Button>\n);\n\nexport default Example;\n";

import QueueExample from "./variants/queue";

const QueueSource = "import { Button } from \"@/registry/erbium/ui/button\";\nimport { toast } from \"@/registry/erbium/ui/toast\";\n\nconst Example = () => (\n  <Button\n    variant=\"outline\"\n    onClick={() => {\n      for (let index = 1; index <= 5; index += 1) {\n        toast.add({ title: `Queue item ${index}`, timeout: 0 });\n      }\n    }}\n  >\n    Show five toasts\n  </Button>\n);\n\nexport default Example;\n";

const meta = {
  title: "UI/Toast",
  component: Toast,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "A succinct message that is displayed temporarily.\n\n**Import:** `@/registry/erbium/ui/toast`\n\n## Usage\n\n```tsx\nimport { toast } from \"@/registry/erbium/ui/toast\";\n```\n\n```tsx\ntoast.add({\n  id: \"event-created\",\n  title: \"Event created\",\n  description: \"Sunday, December 3 at 9:00 AM\",\n});\n```\n\nRepeated calls without an ID create separate notifications. Supply a stable `id` to update an existing toast in place; repeating unchanged content replays its shake and refreshes its timer. `Toaster` has no presentation props: it uses Erbium’s lit surface, built-in status icons and close button, a three-toast preview, and a scrollable full queue on hover or keyboard focus. Swipe toward the inline end to dismiss (right in LTR, left in RTL; the direction comes from `DirectionProvider`). Press F6 to move focus into the stack; Escape dismisses the focused toast. Base UI keeps control of the timer, swipe, and focus behavior. For toast options, use Base UI’s `timeout` and `actionProps` names instead of Sonner’s `duration` and `action`. Sonner’s theme, rich-color, icon, position, and toaster-ID options are intentionally omitted. Base UI’s promise states, priority announcements, and `onClose`/`onRemove` callbacks remain available.\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Toast](https://base-ui.com/react/components/toast)",
      },
    },
  },
} satisfies Meta<typeof Toast>;

export default { ...meta, parameters: { ...meta.parameters, docs: { ...meta.parameters.docs, container: ToastDocsContainer } }, decorators: [(Story, context) => <ShowcaseProviders toast={true && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<{
  type: "success" | "info" | "warning" | "error";
  description: string;
}> = {
  args: { type: "success", description: "Saved successfully" },
  argTypes: {
    type: { control: "select", options: ["success", "info", "warning", "error"] },
    description: { control: "text" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Types: Story = {
  parameters: {
    docs: {
      description: { story: "Set `type` to success, info, warning, error, or loading to show a status icon." },
      source: { code: TypesSource },
    },
  },
  render: TypesExample,
};

export const Promise: Story = {
  parameters: {
    docs: {
      description: { story: "Use `toast.promise` to update one toast as an asynchronous task moves through\n\nloading, success, and error states." },
      source: { code: PromiseSource },
    },
  },
  render: PromiseExample,
};

export const Action: Story = {
  parameters: {
    docs: {
      description: { story: "Pass button props with `actionProps` to render an action.\n\n```tsx\nconst id = toast.add({\n  id: \"event-created\",\n  title: \"Event created\",\n  actionProps: {\n    children: \"Undo\",\n    onClick() {\n      toast.close(id);\n    },\n  },\n});\n```" },
      source: { code: ActionSource },
    },
  },
  render: ActionExample,
};

export const Progress: Story = {
  parameters: {
    docs: {
      description: { story: "Use the ID returned by `toast.add` to update a specific toast. Call `toast.close(id)` to dismiss it." },
      source: { code: ProgressSource },
    },
  },
  render: ProgressExample,
};

export const Queue: Story = {
  parameters: {
    docs: {
      description: { story: "Add five persistent notifications, then hover the stack to see and scroll the full queue." },
      source: { code: QueueSource },
    },
  },
  render: QueueExample,
};

